// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "../ribbon/topbar.js";
import "./cell_style_dialog.js";
import "./print_settings_dialog.js";

/* Print preview — swaps the ribbon into preview mode, renders one of 5
 * starter report templates onto A4 pages, prints via window.print().
 *
 * Five templates:
 *   class    — Timetable for each class (one A4 per class)
 *   teacher  — Timetable for each teacher
 *   room     — Timetable for each classroom
 *   summary  — Summary of all classes on one grid
 *   poster   — Wall poster (landscape, big cells)
 *
 * Defers the 19 other CLASSIC templates.
 */
(function () {
  "use strict";
  const APP = window.APP;
  const notify = window._chrxNotify || console.log;
  const DAYS = ["Mon","Tue","Wed","Thu","Fri","Sat"];

  let overlay = null;
  let docShell = null;
  let pageIdx = 0;
  let pages = [];
  let currentTemplate = "class";
  let zoom = 1;

  function ensureOverlay() {
    if (overlay) return overlay;
    overlay = document.createElement("div");
    overlay.className = "chrx-preview-overlay";
    overlay.innerHTML = '<div class="chrx-preview-shell"></div>';
    document.body.appendChild(overlay);
    return overlay;
  }

  function el(tag, attrs, ...kids) {
    const n = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === "class") n.className = attrs[k];
      else if (k === "html") n.innerHTML = attrs[k];
      else if (k.startsWith("on") && typeof attrs[k] === "function") n.addEventListener(k.slice(2), attrs[k]);
      else if (attrs[k] != null) n.setAttribute(k, attrs[k]);
    }
    for (const c of kids) { if (c == null) continue; n.appendChild(typeof c === "string" ? document.createTextNode(c) : c); }
    return n;
  }

  function buildPreviewBar() {
    const bar = el("div", { class: "chrx-preview-controls",
      style: "display:flex;gap:6px;align-items:center;padding:8px 12px;background:var(--chrx-bg-panel);border-bottom:1px solid var(--chrx-line);flex-wrap:wrap" });

    const prev   = el("button", { class: "chrx-tb-btn", type: "button", onclick: () => stepPage(-1) }, "◀ Prev");
    const next   = el("button", { class: "chrx-tb-btn", type: "button", onclick: () => stepPage(1)  }, "Next ▶");
    const print  = el("button", { class: "chrx-tb-btn chrx-tb-btn--primary", type: "button",
      onclick: printAllPages }, "🖨 Print");
    const indicator = el("span", { class: "chrx-pp-indicator", style: "min-width:80px;text-align:center;font-variant-numeric:tabular-nums" }, "Page 1 / 1");

    const sel = el("select", { class: "chrx-tb-btn", "aria-label": "Report template",
      onchange: (e) => {
        // Reset any per-report customisations when switching reports
        if (APP.activePrintReport && APP.activePrintReport._presetId !== e.target.value) {
          APP.activePrintReport = null;
        }
        render(e.target.value);
      } });
    // Pull the full template list from the registry if it loaded; fall back
    // to the legacy 5-template hardcoded list otherwise.
    const reg = APP.printTemplates;
    const templates = reg ? reg.list() : [
      { id: "class",   name: "Timetable for each class" },
      { id: "teacher", name: "Timetable for each teacher" },
      { id: "room",    name: "Timetable for each room" },
      { id: "summary", name: "Summary of classes" },
      { id: "poster",  name: "Wall poster (landscape)" },
    ];
    templates.forEach(t => sel.appendChild(el("option", { value: t.id }, t.name)));
    sel.value = currentTemplate;

    const filterBtn  = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Filter — pick which classes / teachers / rooms / subjects / periods / days to print",
      onclick: () => {
        const FilterDlg = window.APP && window.APP.PrintFilterDialog;
        const Schema = window.APP && window.APP.PrintReportSchema;
        const Presets = window.APP && window.APP.PrintPresets;
        if (FilterDlg && Schema && Presets) {
          if (!APP.activePrintReport || APP.activePrintReport._presetId !== currentTemplate) {
            const preset = Presets.get(currentTemplate);
            if (preset) {
              const r = Schema.create({ context: preset.context });
              Schema.applyPreset(r, preset);
              r._presetId = preset.id;
              APP.activePrintReport = r;
            }
          }
          if (APP.activePrintReport) {
            FilterDlg.open(APP.activePrintReport, () => render(currentTemplate));
            return;
          }
        }
        // Fallback: legacy prompt
        const q = prompt("Filter rows (subject / teacher / class — leave empty to clear):", APP.printFilter || "");
        if (q == null) return;
        APP.printFilter = q.trim();
        render(currentTemplate);
        notify(q ? ("Filter: " + q) : "Filter cleared");
      } }, "⚙︎ Filter");
    function ensureActiveReport() {
      const Schema = window.APP && window.APP.PrintReportSchema;
      const Presets = window.APP && window.APP.PrintPresets;
      if (!Schema || !Presets) return false;
      if (!APP.activePrintReport || APP.activePrintReport._presetId !== currentTemplate) {
        const preset = Presets.get(currentTemplate);
        if (preset) {
          const r = Schema.create({ context: preset.context });
          Schema.applyPreset(r, preset);
          r._presetId = preset.id;
          APP.activePrintReport = r;
        }
      }
      return !!APP.activePrintReport;
    }
    const sizeBtn    = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Sizes / widths — orientation, pages per sheet, copies",
      onclick: () => {
        if (ensureActiveReport() && window.APP?.PrintSizesDialog) {
          window.APP.PrintSizesDialog.open(APP.activePrintReport, () => render(currentTemplate));
          return;
        }
        window.PrintSettingsDialog && window.PrintSettingsDialog.open("sizes");
      } }, "📐 Sizes/widths");
    const styleBtn   = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Cell style — per-element layout, font, B/I/U for every card",
      onclick: () => {
        if (!window.CellStyleDialog) { notify("Cell-style dialog not loaded", "error"); return; }
        const cur = (APP.printCellStyles || {})[currentTemplate];
        window.CellStyleDialog.open(currentTemplate, cur, () => render(currentTemplate));
      } }, "🎨 Style");
    const designBtn  = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Design — print logo + header / footer text",
      onclick: () => {
        if (ensureActiveReport() && window.APP?.PrintDesignDialog) {
          window.APP.PrintDesignDialog.open(APP.activePrintReport, () => render(currentTemplate));
          return;
        }
      } }, "🖼 Design");
    const colorBtn   = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Colors — card / row-header / column-header",
      onclick: () => {
        if (ensureActiveReport() && window.APP?.PrintColorsDialog) {
          window.APP.PrintColorsDialog.open(APP.activePrintReport, () => render(currentTemplate));
          return;
        }
        window.PrintSettingsDialog && window.PrintSettingsDialog.open("colors");
      } }, "🌈 Colors");
    const structBtn  = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Modify structure — choose what's in pages / rows / columns / cells",
      onclick: () => {
        // Open the new Modify-Structure dialog if pivot engine is loaded
        const ModDlg = window.APP && window.APP.ModifyStructureDialog;
        const Schema = window.APP && window.APP.PrintReportSchema;
        const Presets = window.APP && window.APP.PrintPresets;
        if (ModDlg && Schema && Presets) {
          // Lazily create activePrintReport from the current preset
          if (!APP.activePrintReport || APP.activePrintReport._presetId !== currentTemplate) {
            const preset = Presets.get(currentTemplate);
            if (preset) {
              const r = Schema.create({ context: preset.context });
              Schema.applyPreset(r, preset);
              r._presetId = preset.id;
              APP.activePrintReport = r;
            }
          }
          if (APP.activePrintReport) {
            ModDlg.open(APP.activePrintReport, () => render(currentTemplate));
            return;
          }
        }
        // Fallback to legacy structure tab
        window.PrintSettingsDialog && window.PrintSettingsDialog.open("structure");
      } }, "🏗 Modify structure");
    const extraBtn   = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Add / edit extra columns and rows (subject counts, lesson totals, …)",
      onclick: () => {
        const ExtrasDlg = window.APP && window.APP.PrintExtrasDialog;
        const Schema = window.APP && window.APP.PrintReportSchema;
        const Presets = window.APP && window.APP.PrintPresets;
        if (ExtrasDlg && Schema && Presets) {
          if (!APP.activePrintReport || APP.activePrintReport._presetId !== currentTemplate) {
            const preset = Presets.get(currentTemplate);
            if (preset) {
              const r = Schema.create({ context: preset.context });
              Schema.applyPreset(r, preset);
              r._presetId = preset.id;
              APP.activePrintReport = r;
            }
          }
          if (APP.activePrintReport) {
            ExtrasDlg.open(APP.activePrintReport, () => render(currentTemplate));
            return;
          }
        }
        // Fallback: legacy toggle
        APP.printExtras = !APP.printExtras;
        host.classList.toggle("chrx-pp-extras", !!APP.printExtras);
        render(currentTemplate);
        notify(APP.printExtras ? "Extras: on" : "Extras: off");
      } }, "➕ Extra columns/rows");
    const globalBtn  = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Bell-times / teacher-names / room-names print toggles",
      onclick: () => window.PrintSettingsDialog && window.PrintSettingsDialog.open("globals") }, "🛠 Global");

    const tuningBtn = el("button", { class: "chrx-tb-btn", type: "button",
      title: "Live aesthetics tuning drawer — card padding, font sizes, colors, and visibility",
      onclick: toggleTuningDrawer }, "🎚 Tuning");

    const zoomOut = el("button", { class: "chrx-tb-btn", type: "button", title: "Zoom out", onclick: () => setZoom(zoom - 0.1) }, "➖");
    const zoomReadout = el("span", { class: "chrx-pp-zoom", title: "Reset zoom to 100%",
      style: "min-width:46px;text-align:center;font-variant-numeric:tabular-nums;cursor:pointer;user-select:none", onclick: () => setZoom(1) }, "100%");
    const zoomIn = el("button", { class: "chrx-tb-btn", type: "button", title: "Zoom in", onclick: () => setZoom(zoom + 0.1) }, "➕");
    const fitBtn = el("button", { class: "chrx-tb-btn", type: "button", title: "Fit page to width", onclick: fitToWidth }, "⤢ Fit");

    const close = el("button", { class: "chrx-tb-btn chrx-tb-btn--danger", type: "button",
      style: "margin-left:auto", onclick: closePreview }, "✕ Close preview");

    [prev, next, print, indicator, sel, zoomOut, zoomReadout, zoomIn, fitBtn, filterBtn, tuningBtn, structBtn, extraBtn, styleBtn, sizeBtn, designBtn, colorBtn, globalBtn, close]
      .forEach(c => bar.appendChild(c));
    bar._indicator = indicator;
    return bar;
  }

  function toggleTuningDrawer() {
    const drawer = document.getElementById("chrx-preview-tuning");
    if (!drawer) return;
    const isHidden = drawer.style.display === "none";
    drawer.style.display = isHidden ? "flex" : "none";
  }

  function buildTuningDrawer() {
    const defaults = {
      padding: 6,
      fontSize: 9.5,
      borderWidth: 1,
      theme: "pastel",
      showSubject: true,
      showTeacher: true,
      showClass: true,
      showRoom: true
    };
    APP.printTuning = APP.printTuning || defaults;
    const t = APP.printTuning;

    const drawer = el("div", {
      id: "chrx-preview-tuning",
      class: "chrx-tuning-drawer",
      style: "width:280px; min-width:280px; max-width:280px; background:var(--chrx-bg-panel); border-left:1px solid var(--chrx-line); display:none; flex-direction:column; padding:16px; overflow-y:auto; gap:16px; box-sizing:border-box;"
    });

    const title = el("h3", {
      style: "font-family:var(--chrx-font-display); font-weight:700; font-size:15px; margin:0 0 4px; color:var(--ink);"
    }, "Aesthetic Tuning");

    drawer.appendChild(title);

    function createSlider(label, key, min, max, step, unit = "") {
      const group = el("div", { style: "display:flex; flex-direction:column; gap:4px;" });
      const header = el("div", { style: "display:flex; justify-content:space-between; font-size:11.5px; color:var(--ink-2); font-weight:500;" });
      const valueSpan = el("span", { style: "font-family:var(--chrx-font-mono); font-size:10.5px;" }, t[key] + unit);
      
      header.appendChild(el("span", null, label));
      header.appendChild(valueSpan);
      group.appendChild(header);

      const slider = el("input", {
        type: "range",
        min: String(min),
        max: String(max),
        step: String(step),
        value: String(t[key]),
        style: "width:100%; cursor:pointer; accent-color:var(--teal); margin:0;",
        oninput: (e) => {
          t[key] = parseFloat(e.target.value);
          valueSpan.textContent = e.target.value + unit;
          render(currentTemplate);
        }
      });
      group.appendChild(slider);
      return group;
    }

    drawer.appendChild(createSlider("Cell Padding", "padding", 2, 16, 1, "px"));
    drawer.appendChild(createSlider("Font Size", "fontSize", 8, 16, 0.5, "px"));
    drawer.appendChild(createSlider("Border Width", "borderWidth", 0, 3, 1, "px"));

    const themeGroup = el("div", { style: "display:flex; flex-direction:column; gap:4px;" });
    themeGroup.appendChild(el("label", { style: "font-size:11.5px; color:var(--ink-2); font-weight:500;" }, "Card Theme"));
    const themeSel = el("select", {
      class: "chrx-tb-btn",
      style: "width:100%; font-size:12px; padding:4px 6px;",
      onchange: (e) => {
        t.theme = e.target.value;
        render(currentTemplate);
      }
    });
    [
      { value: "pastel", name: "Soft Pastel" },
      { value: "mono", name: "Monochrome" },
      { value: "neon", name: "Vibrant Neon" },
      { value: "classic", name: "Classic XML" }
    ].forEach(opt => {
      themeSel.appendChild(el("option", { value: opt.value, selected: t.theme === opt.value ? "true" : null }, opt.name));
    });
    themeGroup.appendChild(themeSel);
    drawer.appendChild(themeGroup);

    const contentGroup = el("div", { style: "display:flex; flex-direction:column; gap:8px;" });
    contentGroup.appendChild(el("label", { style: "font-size:11.5px; color:var(--ink-2); font-weight:500; margin-bottom:2px;" }, "Visible Elements"));
    
    function createCheckbox(label, key) {
      const row = el("label", { style: "display:flex; align-items:center; gap:8px; font-size:12px; color:var(--ink-2); cursor:pointer; user-select:none;" });
      const cb = el("input", {
        type: "checkbox",
        checked: t[key] ? "true" : null,
        style: "cursor:pointer; accent-color:var(--teal); margin:0;",
        onchange: (e) => {
          t[key] = e.target.checked;
          render(currentTemplate);
        }
      });
      row.appendChild(cb);
      row.appendChild(document.createTextNode(label));
      return row;
    }

    contentGroup.appendChild(createCheckbox("Subject Code", "showSubject"));
    contentGroup.appendChild(createCheckbox("Teacher Initials", "showTeacher"));
    contentGroup.appendChild(createCheckbox("Class Name", "showClass"));
    contentGroup.appendChild(createCheckbox("Room Name", "showRoom"));
    drawer.appendChild(contentGroup);

    return drawer;
  }

  function openPreview() {
    if (!APP.school) { notify("Open a timetable first.", "error"); return; }
    ensureOverlay();
    const shell = overlay.querySelector(".chrx-preview-shell");
    shell.innerHTML = "";
    const bar = buildPreviewBar();
    shell.appendChild(bar);
    
    const mainArea = el("div", { class: "chrx-preview-main-area", style: "display:flex; flex:1; overflow:hidden;" });
    docShell = el("div", { class: "chrx-preview-doc", style: "flex:1; overflow:auto;" });
    // Ctrl/⌘ + wheel zooms the preview (like a PDF viewer); plain wheel scrolls.
    docShell.addEventListener("wheel", (e) => {
      if (e.ctrlKey || e.metaKey) { e.preventDefault(); setZoom(zoom + (e.deltaY < 0 ? 0.08 : -0.08)); }
    }, { passive: false });
    // Click any timetable cell to open the per-element style dialog for that
    // card (aSc parity). Edits apply to the live report and re-render.
    docShell.addEventListener("click", (e) => {
      const td = e.target && e.target.closest && e.target.closest("td.chrx-pivot-datacell");
      if (!td || !td._cards) return;
      if (!window.CellStyleDialog) { notify("Cell-style dialog not loaded", "error"); return; }
      const Schema = window.APP && window.APP.PrintReportSchema;
      const Presets = window.APP && window.APP.PrintPresets;
      if (Schema && Presets && (!APP.activePrintReport || APP.activePrintReport._presetId !== currentTemplate)) {
        const preset = Presets.get(currentTemplate);
        if (preset) {
          const r = Schema.create({ context: preset.context });
          Schema.applyPreset(r, preset);
          r._presetId = preset.id;
          APP.activePrintReport = r;
        }
      }
      if (!APP.activePrintReport) return;
      window.CellStyleDialog.open({
        mode: "single-card", report: APP.activePrintReport, cards: td._cards,
        onSave: () => render(currentTemplate),
      });
    });
    mainArea.appendChild(docShell);
    
    const tuningDrawer = buildTuningDrawer();
    mainArea.appendChild(tuningDrawer);
    
    shell.appendChild(mainArea);
    overlay.classList.add("is-open");

    // Set ribbon mode (other agents may want to know)
    const host = document.getElementById("chrx-ribbon");
    if (host) host.setAttribute("data-ribbon-mode", "preview");

    render(currentTemplate);

    document.addEventListener("keydown", onKey);
  }

  function closePreview() {
    if (!overlay) return;
    overlay.classList.remove("is-open");
    const host = document.getElementById("chrx-ribbon");
    if (host) host.removeAttribute("data-ribbon-mode");
    document.removeEventListener("keydown", onKey);
  }

  function onKey(e) {
    if (!overlay || !overlay.classList.contains("is-open")) return;
    if (e.key === "Escape")     { e.preventDefault(); closePreview(); }
    if (e.key === "ArrowLeft")  { e.preventDefault(); stepPage(-1); }
    if (e.key === "ArrowRight") { e.preventDefault(); stepPage(1); }
    if ((e.metaKey || e.ctrlKey) && (e.key === "p" || e.key === "P")) {
      e.preventDefault(); printAllPages();
    }
  }

  function stepPage(delta) {
    if (!pages.length) return;
    pageIdx = Math.max(0, Math.min(pages.length - 1, pageIdx + delta));
    showPage(pageIdx);
  }

  // The previewer keeps a single page in the DOM at a time, but window.print()
  // only sends whatever is currently in the DOM to the printer. Without this
  // helper, clicking 🖨 Print would drop every page except the one on screen —
  // surfacing as "only Monday / only the first class printed". Mount every
  // page into docShell for the duration of print(), then restore single-page
  // view afterwards. .chrx-preview-page already has page-break-after:always
  // in the print CSS so each page gets its own physical sheet.
  function printAllPages() {
    if (!pages.length || !docShell) { window.print(); return; }
    // Strip the on-screen zoom so the printout uses the true A4 page size,
    // not whatever magnification the user is previewing at.
    pages.forEach(p => { p.style.zoom = "1"; });
    const saved = pageIdx;
    if (pages.length > 1) {
      while (docShell.firstChild) docShell.removeChild(docShell.firstChild);
      for (const p of pages) docShell.appendChild(p);
    }
    try { window.print(); }
    finally { showPage(saved); }  // re-mounts current page + re-applies zoom
  }
  function showPage(i) {
    docShell.innerHTML = "";
    docShell.appendChild(pages[i]);
    const ind = overlay.querySelector(".chrx-pp-indicator");
    if (ind) ind.textContent = `Page ${i + 1} / ${pages.length}`;
    // Now the page is in the live DOM with real geometry — run the measure-
    // and-fit pass so cell text shrinks to fit instead of ballooning rows.
    try { autofitMountedPage(pages[i]); } catch (e) { /* never break preview */ }
    applyZoom();
  }

  /* Preview zoom (screen only — the actual print uses the real A4 page size).
   * CSS `zoom` reflows the page so docShell's scrollbars track the scaled
   * size naturally; cleaner than transform:scale for a scroll container. */
  function applyZoom() {
    const page = pages[pageIdx];
    if (page) page.style.zoom = String(zoom);
    const r = overlay && overlay.querySelector(".chrx-pp-zoom");
    if (r) r.textContent = Math.round(zoom * 100) + "%";
  }

  function setZoom(z) {
    zoom = Math.max(0.3, Math.min(2.5, Math.round(z * 100) / 100));
    applyZoom();
  }

  function fitToWidth() {
    const page = pages[pageIdx];
    if (!page || !docShell) return;
    page.style.zoom = "1";
    const avail = docShell.clientWidth - 24;
    const pageW = page.getBoundingClientRect().width;
    if (pageW > 0) setZoom(avail / pageW);
  }

  /* aSc-style shrink-to-fit. The CSS cqi+clamp() in the cell renderer is a
   * pre-layout *estimate*; once a page is mounted we have real pixel sizes,
   * so lock every body cell to its layout height (so long content can't
   * grow the row) and binary-search the font size down until the content
   * fits the box. Works for both absolute-anchored cells (per-class grids)
   * and flow cells (summary/aggregate) because overflow is measured via the
   * descendants' bounding boxes against the cell rect — structure-agnostic.
   * Runs in the browser only; jsdom has no layout so this is a no-op there. */
  function autofitMountedPage(pageEl) {
    if (!pageEl || typeof pageEl.querySelectorAll !== "function") return;
    const grid = pageEl.querySelector("table.chrx-pivot-grid");
    if (!grid) return;
    const tds = grid.querySelectorAll("tbody td");
    if (!tds.length || tds.length > 1500) return; // safety valve for huge grids
    tds.forEach(td => {
      const cell = td.querySelector(".chrx-pivot-cell");
      if (!cell || cell.dataset.fit) return;
      const h = parseFloat(td.style.height) || td.clientHeight;
      if (!h) return;
      // Lock the cell to its intended height; clip overflow so a long class
      // list can't push the whole row taller (the ballooning we saw).
      cell.style.height = h + "px";
      cell.style.overflow = "hidden";
      const texts = Array.from(cell.querySelectorAll("div"))
        .filter(d => d.firstChild && d.textContent.trim());
      if (!texts.length) { cell.dataset.fit = "1"; return; }
      const rect = cell.getBoundingClientRect();
      const overflowing = () => {
        for (const t of texts) {
          const r = t.getBoundingClientRect();
          if (r.right > rect.right + 0.6 || r.bottom > rect.bottom + 0.6) return true;
        }
        return false;
      };
      if (!overflowing()) { cell.dataset.fit = "1"; return; }
      const bases = texts.map(t => parseFloat(getComputedStyle(t).fontSize) || 9);
      let lo = 0.4, hi = 1.0, best = 0.4;
      for (let it = 0; it < 6; it++) {
        const mid = (lo + hi) / 2;
        texts.forEach((t, i) => { t.style.fontSize = (bases[i] * mid).toFixed(2) + "px"; });
        if (overflowing()) hi = mid; else { best = mid; lo = mid; }
      }
      texts.forEach((t, i) => { t.style.fontSize = (bases[i] * best).toFixed(2) + "px"; });
      cell.dataset.fit = "1";
    });
  }

  // ─── Render templates ────────────────────────────────────────────────────
  function render(template) {
    currentTemplate = template;
    pageIdx = 0;
    pages = [];
    const s = APP.school;
    const periods = s.bell?.periods || [];

    // Registry-first dispatch: pivot-engine presets register with the same
    // IDs as the legacy 5 builtins (class/teacher/room/summary/poster) and
    // win. `builtin:true` registry entries are placeholders without a real
    // render fn, so we only honour registry when a non-builtin render exists.
    const reg = APP.printTemplates;
    const def = reg ? reg.get(template) : null;
    if (def && !def.builtin && typeof def.render === "function") {
      try {
        // Pass `periods` so the pivot engine can honor the school's actual
        // bell schedule. Without this, periods defaulted to 8 regardless,
        // and break periods (gaps in the bell) silently mismatched cards.
        const out = def.render(s, periods);
        if (Array.isArray(out))      pages = out.filter(Boolean);
        else if (out instanceof Node) pages = [out];
      } catch (err) {
        console.error("[print_preview] template", template, "threw:", err);
        pages = [el("div", { class: "chrx-preview-page" },
          el("h2", null, "Template error"),
          el("pre", { style: "white-space:pre-wrap;color:#900;font-size:11px" }, String(err && err.message || err)))];
      }
    }

    // Fallback to legacy hardcoded renderers for the 5 builtins when no
    // pivot preset has claimed the same ID (e.g., during transition).
    if (!pages.length) {
      if (template === "class")        pages = perEntityPages(s, "class",   periods, s.classes,    s._idx?.cardsByClass);
      else if (template === "teacher") pages = perEntityPages(s, "teacher", periods, s.teachers,   s._idx?.cardsByTeacher);
      else if (template === "room")    pages = perEntityPages(s, "room",    periods, s.classrooms, s._idx?.cardsByRoom);
      else if (template === "summary") pages = [summaryPage(s, periods)];
      else if (template === "poster")  pages = [posterPage(s, periods)];
    }

    if (!pages.length) pages = [el("div", { class: "chrx-preview-page" }, el("h2", null, "No data"))];
    showPage(0);
  }

  function pageHeader(title, subtitle) {
    return el("div", { style: "display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #333;padding-bottom:4px;margin-bottom:8px" },
      el("h2", null, title),
      el("div", { style: "font-size:9.5px;color:#555" }, subtitle || ""));
  }

  function timeToMin(timeStr) {
    if (!timeStr) return -1;
    const m = String(timeStr).match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return -1;
    return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
  }

  function getBreakBetween(school, p1, p2) {
    if (!school || !school.breaks || !p1 || !p2) return null;
    const t1 = p1.endMin;
    const t2 = p2.startMin;
    if (t2 <= t1) return null;
    for (const b of school.breaks) {
      const bStart = timeToMin(b.starttime);
      const bEnd = timeToMin(b.endtime);
      if (bStart !== -1 && bEnd !== -1) {
        if (bStart >= t1 - 5 && bEnd <= t2 + 5) {
          return b;
        }
      }
    }
    return null;
  }

  function gridTable(periods, daysIn, cellFn) {
    const s = APP.school;
    const sortedPeriods = periods.slice().sort((a, b) => (a.startMin || 0) - (b.startMin || 0));
    const tbl = el("table", { class: "chrx-print-table" });
    const tr0 = el("tr");
    tr0.appendChild(el("th", { class: "chrx-print-th-corner" }, ""));
    
    sortedPeriods.forEach((p, idx) => {
      tr0.appendChild(el("th", { class: "chrx-print-th-period" }, "P" + p.index + " " + p.label));
      if (idx < sortedPeriods.length - 1) {
        const brk = getBreakBetween(s, p, sortedPeriods[idx + 1]);
        if (brk) {
          tr0.appendChild(el("th", { class: "chrx-print-th-break" }, ""));
        }
      }
    });
    tbl.appendChild(el("thead", null, tr0));
    
    const tb = el("tbody");
    daysIn.forEach((d, di) => {
      const tr = el("tr");
      tr.appendChild(el("th", { class: "chrx-print-th-day" }, DAYS[di]));
      
      sortedPeriods.forEach((p, idx) => {
        tr.appendChild(cellFn(di, p));
        if (idx < sortedPeriods.length - 1) {
          const brk = getBreakBetween(s, p, sortedPeriods[idx + 1]);
          if (brk) {
            if (di === 0) {
              const breakCell = el("td", {
                class: "chrx-print-td-break",
                rowspan: String(daysIn.length),
                style: "vertical-align:middle; text-align:center; background:var(--paper-2); font-weight:600; text-transform:uppercase; color:var(--ink-3); font-size:10px; padding:4px;"
              });
              const textDiv = el("div", {
                style: "writing-mode: vertical-lr; transform: rotate(180deg); margin: 0 auto; letter-spacing: 0.15em;"
              }, brk.printtext || brk.name);
              breakCell.appendChild(textDiv);
              tr.appendChild(breakCell);
            }
          }
        }
      });
      tb.appendChild(tr);
    });
    tbl.appendChild(tb);
    return tbl;
  }

  function cellFromCard(card) {
    const tuning = APP.printTuning || {
      padding: 6,
      fontSize: 9.5,
      borderWidth: 1,
      theme: "pastel",
      showSubject: true,
      showTeacher: true,
      showClass: true,
      showRoom: true
    };

    if (!card) {
      return el("td", {
        class: "pp-cell-empty",
        style: `padding:${tuning.padding}px; font-size:${tuning.fontSize}px; border-width:${tuning.borderWidth}px; border-style:solid; border-color:var(--line); color:var(--ink-3); text-align:center; vertical-align:middle;`
      }, "—");
    }

    const hue = card.subjectAbbr ? subjectHue({ abbr: card.subjectAbbr, name: card.subject }) : 210;
    
    let bg = "var(--paper)";
    let fg = "var(--ink)";
    let border = `1px solid var(--line)`;
    
    if (tuning.theme === "pastel") {
      bg = `hsla(${hue}, 70%, 96%, 0.9)`;
      fg = `hsl(${hue}, 75%, 22%)`;
      border = `${tuning.borderWidth}px solid hsl(${hue}, 60%, 45%)`;
    } else if (tuning.theme === "mono") {
      bg = "#f3f4f6";
      fg = "#1f2937";
      border = `${tuning.borderWidth}px solid #d1d5db`;
    } else if (tuning.theme === "neon") {
      bg = `hsla(${hue}, 80%, 93%, 1)`;
      fg = `hsl(${hue}, 90%, 18%)`;
      border = `${tuning.borderWidth}px solid hsl(${hue}, 85%, 38%)`;
    } else { // classic
      bg = card.color || "var(--paper)";
      fg = "var(--ink)";
      border = `${tuning.borderWidth}px solid var(--line)`;
    }

    const td = el("td", {
      style: `background:${bg}; color:${fg}; border:${border}; padding:${tuning.padding}px; font-size:${tuning.fontSize}px; vertical-align:middle;`
    });

    const box = el("div", {
      style: "display:flex; flex-direction:column; justify-content:center; align-items:center; text-align:center; gap:2px; height:100%;"
    });

    if (tuning.showSubject) {
      box.appendChild(el("div", { style: "font-weight:750; font-family:var(--chrx-font-display); line-height:1.15; font-size:1.15em;" }, card.subjectAbbr || card.subject || ""));
    }
    
    const metaText = [];
    if (tuning.showTeacher && card.teachers?.length) {
      metaText.push(card.teachers.join(", "));
    }
    if (tuning.showRoom && card.classroom) {
      metaText.push(card.classroom);
    }
    if (tuning.showClass && (card.classes?.length || card.class?.length)) {
      metaText.push(card.classes || card.class);
    }

    if (metaText.length) {
      box.appendChild(el("div", {
        style: "font-size:0.88em; opacity:0.85; line-height:1.2; font-family:var(--chrx-font-sans);"
      }, metaText.join(" · ")));
    }

    td.appendChild(box);
    return td;
  }

  function perEntityPages(school, kind, periods, entities, byIdx) {
    if (!entities || !entities.length) return [];
    return entities.map(ent => {
      const page = el("div", { class: "chrx-preview-page" });
      page.appendChild(pageHeader(
        ent.name + (kind === "class" ? "" : kind === "teacher" ? " (Teacher)" : " (Room)"),
        school.schoolName || ""));
      const list = (byIdx && byIdx[ent.id]) || [];
      const tbl = gridTable(periods, DAYS, (di, p) => {
        let card = null;
        if (kind === "class")        card = list.find(c => c.day === di && c.period === p.index);
        else if (kind === "teacher") card = list.find(c => c.day === di && c.period === p.index);
        else                          card = list.find(c => c.day === di && c.period === p.index);
        return cellFromCard(card);
      });
      page.appendChild(tbl);
      page.appendChild(el("div", { style: "font-size:9px;color:#999;text-align:right;margin-top:6px" },
        "Chronexa · " + new Date().toLocaleDateString()));
      return page;
    });
  }

  function summaryPage(school, periods) {
    const page = el("div", { class: "chrx-preview-page" });
    page.appendChild(pageHeader("Summary of classes", school.schoolName || ""));
    const tbl = el("table");
    const tr0 = el("tr"); tr0.appendChild(el("th", null, "Class"));
    DAYS.forEach((d) => tr0.appendChild(el("th", null, d)));
    tbl.appendChild(el("thead", null, tr0));
    const tb = el("tbody");
    const byClass = school._idx?.cardsByClass || {};
    for (const c of school.classes) {
      const tr = el("tr");
      tr.appendChild(el("th", null, c.name));
      const list = byClass[c.id] || [];
      DAYS.forEach((_, di) => {
        const subjects = periods.map(p => {
          const card = list.find(x => x.day === di && x.period === p.index);
          return card ? (card.subjectAbbr || card.subject || "·").slice(0, 5) : "·";
        }).join(" ");
        tr.appendChild(el("td", { style: "font-size:8.5px;font-family:monospace;letter-spacing:0.5px" }, subjects));
      });
      tb.appendChild(tr);
    }
    tbl.appendChild(tb); page.appendChild(tbl);
    return page;
  }

  function posterPage(school, periods) {
    const page = el("div", { class: "chrx-preview-page",
      style: "width:297mm;min-height:210mm;padding:10mm 12mm" });
    page.appendChild(pageHeader("Wall poster · " + (school.schoolName || ""), new Date().toLocaleDateString()));
    const byClass = school._idx?.cardsByClass || {};
    const grid = el("div", { style: "display:grid;grid-template-columns:repeat(" + (school.classes.length + 1) + ",1fr);gap:1px;background:#999;border:1px solid #444" });
    grid.appendChild(headerCell("Period"));
    school.classes.forEach(c => grid.appendChild(headerCell(c.name)));
    for (let di = 0; di < DAYS.length; di++) {
      for (const p of periods) {
        grid.appendChild(headerCell(DAYS[di] + " P" + p.index));
        for (const c of school.classes) {
          const list = byClass[c.id] || [];
          const card = list.find(x => x.day === di && x.period === p.index);
          grid.appendChild(posterCell(card));
        }
      }
    }
    page.appendChild(grid);
    return page;
  }
  function headerCell(s) { return el("div", { style: "background:#eee;padding:3px 5px;font-size:8px;font-weight:600;text-align:center" }, s); }
  function posterCell(card) {
    if (!card) return el("div", { style: "background:#fff;padding:2px;min-height:18px" });
    return el("div", { style: "background:#fff;padding:2px;min-height:18px;font-size:8px;line-height:1.1" },
      el("div", { style: "font-weight:600" }, card.subjectAbbr || card.subject || ""),
      el("div", { style: "color:#666" }, (card.teachers || []).join(",").slice(0, 12)));
  }

  // ─── Wire events ─────────────────────────────────────────────────────────
  window.addEventListener("app:print-preview", openPreview);
  window.addEventListener("app:preview-close", closePreview);
  window.addEventListener("app:preview-prev",  () => stepPage(-1));
  window.addEventListener("app:preview-next",  () => stepPage(1));
  window.addEventListener("app:preview-template", (e) => render(e.detail?.template || "class"));
  window.addEventListener("keydown", (e) => {
    if ((e.metaKey || e.ctrlKey) && (e.key === "p" || e.key === "P") && !overlay?.classList.contains("is-open")) {
      e.preventDefault(); openPreview();
    }
  });

  APP.printPreview = { open: openPreview, close: closePreview, render };
})();
